create table public.legacy_exam_question_banks (
  id boolean primary key default true check (id),
  banks jsonb not null check (jsonb_typeof(banks) = $json_type$object$json_type$),
  updated_at timestamptz not null default now()
);

alter table public.legacy_exam_question_banks enable row level security;
revoke all on table public.legacy_exam_question_banks from public, anon, authenticated;
grant select on table public.legacy_exam_question_banks to service_role;

insert into public.legacy_exam_question_banks (id, banks)
values (true, $legacy_banks${"10-متقدم":[{"id":"10P-01","qAr":"في أي نموذج ذري تتحرك الإلكترونات في مدارات دائرية؟","qEn":"Electrons move in circular orbits in which atomic model?","options":[{"ar":"نموذج ميكانيكا الكم","en":"quantum mechanical model"},{"ar":"نموذج رذرفورد","en":"Rutherford's model"},{"ar":"نموذج بور","en":"Bohr's model"},{"ar":"نموذج فطيرة الكعك","en":"plum-pudding model"}],"answer":2},{"id":"10P-02","qAr":"أي مما يأتي صحيح بالنسبة للشكل المقابل لحالة الذرة؟","qEn":"Which of the following is true about the figure of atomic states:","mediaHtml":"<div class=\"q-media\"><img src=\"https://i.postimg.cc/q7Fzk0yD/Screenshot-2026-09-05-180732.png\" alt=\"Ground and excited states\"></div>","options":[{"ar":"(A) في حالة مثارة، (B) في حالة استقرار","en":"(A) in excited state, (B) in ground state."},{"ar":"(A) في حالة استقرار، (B) في حالة مثارة","en":"(A) in ground state, (B) in excited state."},{"ar":"(A) في حالة استقرار، (B) في حالة استقرار","en":"(A) in ground state, (B) in ground state."},{"ar":"(A) في حالة مثارة، (B) في حالة مثارة","en":"(A) in excited state, (B) in excited state."}],"answer":1},{"id":"10P-03","qAr":"ما هو العدد الأقصى للإلكترونات التي يمكن أن توجد في كل مستوى طاقة رئيسي؟","qEn":"What is the maximum number of electrons that can be present in each principal energy level?","options":[{"ar":"n","en":"n"},{"ar":"n²","en":"n²"},{"ar":"2n","en":"2n"},{"ar":"2n²","en":"2n²"}],"answer":3},{"id":"10P-04","qAr":"ماذا يسمى أدنى مستوى طاقة للذرة؟","qEn":"What is the lowest energy state of an atom called?","options":[{"ar":"حالة الاستقرار","en":"the ground state"},{"ar":"الحالة المثارة","en":"the excited state"},{"ar":"الحالة الصلبة","en":"the solid state"},{"ar":"الحالة العشوائية","en":"the chaotic state"}],"answer":0},{"id":"10P-05","qAr":"يتكون مستوى الطاقة الرئيس 3 من كم مستوى فرعي؟","qEn":"Principal energy level 3 consists of how many sublevels?","options":[{"ar":"3s, 3p, 3f","en":"3s, 3p, 3f"},{"ar":"3s, 3p, 3d","en":"3s, 3p, 3d"},{"ar":"2s, 2d","en":"2s, 2d"},{"ar":"2s, 2f","en":"2s, 2f"}],"answer":1},{"id":"10P-06","qAr":"أي العبارات التالية يصف بشكل صحيح نموذج بور لذرة الهيدروجين؟","qEn":"Which statement correctly describes Bohr's model of hydrogen atom?","options":[{"ar":"الإلكترونات تتحرك في مدارات عشوائية دون مستويات","en":"Electrons move in random orbits without defined levels"},{"ar":"الإلكترونات تتحرك في مدارات دائرية ولا تشع طاقة إلا عند الانتقال","en":"Electrons move in circular orbits and radiate energy only on transition"},{"ar":"النواة تحتوي على جسيمات عشوائية","en":"Nucleus contains random particles"},{"ar":"الإلكترونات تشع طاقة باستمرار","en":"Electrons continuously radiate energy"}],"answer":1},{"id":"10P-07","qAr":"ماذا يحدث لطاقة المدار ونصف قطره كلما ابتعدنا عن النواة؟","qEn":"What happens to orbital energy and radius as we move further from nucleus?","options":[{"ar":"تزداد طاقة المدار ويزداد نصف قطره","en":"Orbital energy increases and its radius increases"},{"ar":"تزداد طاقة المدار ويقل نصف قطره","en":"Orbital energy increases and its radius decreases"},{"ar":"تظل الطاقة ونصف القطر ثابتين","en":"Energy and radius remain constant"},{"ar":"تقل طاقة المدار ويزداد نصف قطره","en":"Orbital energy decreases and its radius increases"}],"answer":0},{"id":"10P-08","qAr":"فيما يتعلق بمخطط الأفلاك أدناه، أي المبادئ تم تعارضها؟","qEn":"Regarding the orbital diagram below, which principles are violated?","mediaHtml":"<div class=\"q-media\"><img src=\"https://i.postimg.cc/rpHvKfVT/Screenshot-2026-09-05-184231.png\" alt=\"Orbital diagram\"></div>","options":[{"ar":"قاعدة هوند ومبدأ أوفباو","en":"Hund's rule and aufbau principle"},{"ar":"مبدأ أوفباو فقط","en":"aufbau principle only"},{"ar":"مبدأ باولي للاستبعاد فقط","en":"Pauli exclusion principle only"},{"ar":"قاعدة هوند ومبدأ باولي للاستبعاد","en":"Hund's rule and Pauli's exclusion principle"}],"answer":3},{"id":"10P-09","qAr":"ما هو التوزيع الإلكتروني للغاز النبيل الصحيح لعنصر النحاس Cu (العدد الذري = 29)؟","qEn":"What is the correct noble-gas notation for copper Cu (Z = 29)?","options":[{"ar":"[Ar] 4s¹ 3d¹⁰","en":"[Ar] 4s¹ 3d¹⁰"},{"ar":"[Ar] 4s¹ 3d⁹ 4p¹","en":"[Ar] 4s¹ 3d⁹ 4p¹"},{"ar":"[Ar] 4s² 3d⁸ 4p¹","en":"[Ar] 4s² 3d⁸ 4p¹"},{"ar":"[Ar] 4s² 3d⁹","en":"[Ar] 4s² 3d⁹"}],"answer":0},{"id":"10P-10","qAr":"ما هي إلكترونات التكافؤ لعنصر غاز النيون Ne (Z = 10)؟","qEn":"What are the valence electrons for Neon (Z = 10)?","options":[{"ar":"2 إلكترونات","en":"2 electrons"},{"ar":"10 إلكترونات","en":"10 electrons"},{"ar":"8 إلكترونات","en":"8 electrons"},{"ar":"6 إلكترونات","en":"6 electrons"}],"answer":2},{"id":"10P-11","qAr":"أي مبدأ ينص على أنه لا يمكن لأي إلكترونين في نفس الذرة أن يكون لهما نفس أعداد الكم الأربعة؟","qEn":"Which principle states no two electrons can have the same set of four quantum numbers?","options":[{"ar":"مبدأ أوفباو","en":"Aufbau principle"},{"ar":"قاعدة هوند","en":"Hund's rule"},{"ar":"مبدأ استبعاد باولي","en":"Pauli exclusion principle"},{"ar":"نظرية الكم","en":"Quantum theory"}],"answer":2},{"id":"10P-12","qAr":"ذرة عنصر الفوسفور P تحتوي على 15 إلكتروناً. ما هو مستوى الطاقة الفرعي الممتلئ جزئياً؟","qEn":"Phosphorus atom (P) has 15 electrons. Which sublevel is partially filled?","options":[{"ar":"4s","en":"4s"},{"ar":"2s","en":"2s"},{"ar":"3p","en":"3p"},{"ar":"2p","en":"2p"}],"answer":2},{"id":"10P-13","qAr":"ما عدد إلكترونات التكافؤ في عناصر المجموعة المبينة أدناه؟","qEn":"What is the number of valence electrons in the group shown below?","mediaHtml":"<div class=\"q-media\"><img src=\"https://i.postimg.cc/8kxMtM55/Screenshot-2026-09-05-185427.png\" alt=\"Valence electrons group 17\"></div>","options":[{"ar":"7","en":"7"},{"ar":"1","en":"1"},{"ar":"8","en":"8"},{"ar":"17","en":"17"}],"answer":0},{"id":"10P-14","qAr":"لماذا يُعتبر الترتيب الإلكتروني لعنصر الكروم Cr = 24 هو [Ar] 4s¹ 3d⁵؟","qEn":"Why is the electron configuration for chromium (Cr = 24) [Ar] 4s¹ 3d⁵?","options":[{"ar":"بسبب ترميز الغاز النبيل","en":"Because of noble gas notation"},{"ar":"بسبب استقرار المستويات نصف الممتلئة s و d","en":"Due to stability of half-filled s and d orbitals"},{"ar":"لأنه في مجمع p","en":"Because it's in p-block"},{"ar":"لأنه يتبع أوفباو فقط","en":"To follow Aufbau only"}],"answer":1},{"id":"10P-15","qAr":"أي مجموعات الجدول الدوري تتميز عناصرها بعدم النشاط الكيميائي؟","qEn":"Which group in the periodic table consists of chemically unreactive elements?","mediaHtml":"<div class=\"q-media\"><img src=\"https://i.postimg.cc/mkLG8zyS/Screenshot-2026-09-13-074947.png\" alt=\"Periodic Table\"></div>","options":[{"ar":"المجموعة 18","en":"Group 18"},{"ar":"المجموعة 2","en":"Group 2"},{"ar":"المجموعة 17","en":"Group 17"},{"ar":"المجموعة 1","en":"Group 1"}],"answer":0},{"id":"10P-16","qAr":"ما الفئة التي تضم العناصر الممثلة في الجدول الدوري (المجموعات 1، 2، ومن 13 إلى 18)؟","qEn":"Which block contains representative elements in the periodic table?","options":[{"ar":"الفئة s والفئة p","en":"s-block and p-block"},{"ar":"الفئة d فقط","en":"d-block only"},{"ar":"الفئة f فقط","en":"f-block only"},{"ar":"اللافلزات الانتقالية","en":"Transition nonmetals"}],"answer":0},{"id":"10P-17","qAr":"ماذا تسمى عناصر الفئة (d) في الجدول الدوري الحديث؟","qEn":"What are the elements of the d-block called?","options":[{"ar":"العناصر الانتقالية","en":"Transition elements"},{"ar":"الفلزات القلوية","en":"Alkali metals"},{"ar":"الغازات النبيلة","en":"Noble gases"},{"ar":"الهالوجينات","en":"Halogens"}],"answer":0},{"id":"10P-18","qAr":"أي مما يلي يُعد رديء التوصيل للحرارة والكهرباء؟","qEn":"Which of the following are poor conductors of heat and electricity?","options":[{"ar":"الفلزات","en":"metals"},{"ar":"أشباه الفلزات","en":"metalloids"},{"ar":"اللافلزات","en":"nonmetals"},{"ar":"الفلزات القلوية الأرضية","en":"alkaline earth elements"}],"answer":2},{"id":"10P-19","qAr":"ماذا تمثل المربعات الخضراء على جانب الخط المتعرج في الشكل أدناه؟","qEn":"What do the green boxes bordering the stairstep line represent?","mediaHtml":"<div class=\"q-media\"><img src=\"https://i.postimg.cc/YSdJ71TR/Screenshot-2026-09-13-141253.png\" alt=\"Metalloids\"></div>","options":[{"ar":"الفلزات","en":"Metals"},{"ar":"اللافلزات","en":"Nonmetals"},{"ar":"أشباه الفلزات","en":"Metalloids"},{"ar":"اللانثانيدات","en":"Lanthanides"}],"answer":2},{"id":"10P-20","qAr":"ما الرقم الذي يمثل الفلزات الانتقالية في الرسم التخطيطي أدناه؟","qEn":"Which number represents transition metals in the diagram below?","mediaHtml":"<div class=\"q-media\"><img src=\"https://i.postimg.cc/FRJQ6Vjz/Screenshot-2026-09-01-122437.png\" alt=\"Periodic table blocks\"></div>","options":[{"ar":"5","en":"5"},{"ar":"6","en":"6"},{"ar":"3","en":"3"},{"ar":"1","en":"1"}],"answer":2},{"id":"10P-21","qAr":"ما الرقم الذي يمثل مجموعة الهالوجينات في الرسم التخطيطي للجدول الدوري؟","qEn":"Which number represents the halogens group in the diagram?","mediaHtml":"<div class=\"q-media\"><img src=\"https://i.postimg.cc/FRJQ6Vjz/Screenshot-2026-09-01-122437.png\" alt=\"Periodic table blocks\"></div>","options":[{"ar":"4","en":"4"},{"ar":"5","en":"5"},{"ar":"1","en":"1"},{"ar":"3","en":"3"}],"answer":0},{"id":"10P-22","qAr":"ما الرقم الذي يمثل مجموعة الغازات النبيلة في الرسم التخطيطي للجدول الدوري؟","qEn":"Which number represents noble gases group in the diagram?","mediaHtml":"<div class=\"q-media\"><img src=\"https://i.postimg.cc/FRJQ6Vjz/Screenshot-2026-09-01-122437.png\" alt=\"Periodic table blocks\"></div>","options":[{"ar":"4","en":"4"},{"ar":"5","en":"5"},{"ar":"1","en":"1"},{"ar":"3","en":"3"}],"answer":1},{"id":"10P-23","qAr":"ما الرقم الذي يمثل مجموعة الفلزات القلوية في الرسم التخطيطي للجدول الدوري؟","qEn":"Which number represents alkali metals group in the diagram?","mediaHtml":"<div class=\"q-media\"><img src=\"https://i.postimg.cc/FRJQ6Vjz/Screenshot-2026-09-01-122437.png\" alt=\"Periodic table blocks\"></div>","options":[{"ar":"4","en":"4"},{"ar":"5","en":"5"},{"ar":"1","en":"1"},{"ar":"3","en":"3"}],"answer":2},{"id":"10P-24","qAr":"ما الرقم الذي يمثل الفلزات القلوية الأرضية في الرسم التخطيطي للجدول الدوري؟","qEn":"Which number represents alkaline earth metals in the diagram?","mediaHtml":"<div class=\"q-media\"><img src=\"https://i.postimg.cc/FRJQ6Vjz/Screenshot-2026-09-01-122437.png\" alt=\"Periodic table blocks\"></div>","options":[{"ar":"2","en":"2"},{"ar":"5","en":"5"},{"ar":"1","en":"1"},{"ar":"3","en":"3"}],"answer":0},{"id":"10P-25","qAr":"أي مما يلي يُعد الترتيب الإلكتروني الصحيح لعنصر في المجموعة 2 والدورة الرابعة؟","qEn":"Which is the correct electron configuration for an element in group 2 and period 4?","options":[{"ar":"[He] 2s² 2p²","en":"[He] 2s² 2p²"},{"ar":"[Ne] 3s² 3p²","en":"[Ne] 3s² 3p²"},{"ar":"[Ar] 4s²","en":"[Ar] 4s²"},{"ar":"[Ar] 4s² 3d²","en":"[Ar] 4s² 3d²"}],"answer":2}],"11-عام":[{"id":"11A-01","qAr":"من هو العالم الذي رتب العناصر تصاعدياً حسب كتلها الذرية ولاحظ تكرار الخواص (قانون الثمانيات)؟","qEn":"Who arranged elements by atomic mass and noticed properties repeated (Law of Octaves)?","options":[{"ar":"جون نيولاندز","en":"John Newlands"},{"ar":"ديميتري مندلييف","en":"Dmitri Mendeleev"},{"ar":"هنري موزلي","en":"Henry Moseley"},{"ar":"لوثر مير","en":"Lothar Meyer"}],"answer":0},{"id":"11A-02","qAr":"على ماذا اعتمد ديميتري مندلييف في ترتيبه للجدول الدوري الأول؟","qEn":"What did Dmitri Mendeleev base his first periodic table on?","options":[{"ar":"الكتلة الذرية والخواص المتشابهة","en":"Atomic mass and similar properties"},{"ar":"العدد الذري فقط","en":"Atomic number only"},{"ar":"التوزيع الإلكتروني","en":"Electron configuration"},{"ar":"نصف القطر الذري","en":"Atomic radius"}],"answer":0},{"id":"11A-03","qAr":"من هو العالم الذي رتب العناصر بناءً على أعدادها الذرية بدلاً من كتلها الذرية؟","qEn":"Which scientist arranged elements by atomic number rather than atomic mass?","options":[{"ar":"هنري موزلي","en":"Henry Moseley"},{"ar":"جون نيولاندز","en":"John Newlands"},{"ar":"ديميتري مندلييف","en":"Dmitri Mendeleev"},{"ar":"جون دالتون","en":"John Dalton"}],"answer":0},{"id":"11A-04","qAr":"لماذا تظهر عناصر مثل الصوديوم \\(_{11}\\text{Na}\\) والبوتاسيوم \\(_{19}\\text{K}\\) سلوكاً كيميائياً متشابهاً؟","qEn":"Why do sodium \\(_{11}\\text{Na}\\) and potassium \\(_{19}\\text{K}\\) show similar chemical behavior?","options":[{"ar":"لانتمائهما للمجموعة 1 وامتلاكهما إلكترون تكافؤ واحد","en":"Belonging to Group 1 and having one valence electron"},{"ar":"لتساوي كتلتهما الذرية","en":"Equal atomic masses"},{"ar":"لتساوي عدد النيوترونات","en":"Equal neutrons"},{"ar":"لوجودهما في نفس الحالة الفيزيائية","en":"Same physical state"}],"answer":0},{"id":"11A-05","qAr":"أي مما يلي صحيح فيما يتعلق بخواص المجموعة 17 (الهالوجينات)؟","qEn":"Which is correct regarding properties of Group 17 (Halogens)?","options":[{"ar":"تمتلك خصائص متشابهة وتميل لاكتساب إلكترون واحد","en":"Similar properties and tend to gain one electron"},{"ar":"جميعها غازات خامدة","en":"All are inert gases"},{"ar":"لها نفس الكتل الذرية","en":"Same atomic masses"},{"ar":"لا تتفاعل أبداً","en":"Never react"}],"answer":0},{"id":"11A-06","qAr":"لماذا تتشابه عناصر المجموعة الواحدة في الخواص الكيميائية؟","qEn":"Why do elements in the same group have similar chemical properties?","options":[{"ar":"لتساوي عدد إلكترونات التكافؤ","en":"Same number of valence electrons"},{"ar":"لتساوي الكتلة الذرية","en":"Same atomic mass"},{"ar":"لتساوي عدد النيوترونات","en":"Same neutrons"},{"ar":"لتساوي عدد البروتونات","en":"Same protons"}],"answer":0},{"id":"11A-07","qAr":"أي العناصر التالية يمتلك خواص كيميائية تشبه عنصر الكالسيوم \\(_{20}\\text{Ca}\\) (المجموعة 2)؟","qEn":"Which element has properties similar to calcium \\(_{20}\\text{Ca}\\) (Group 2)?","options":[{"ar":"الكلور \\(_{17}\\text{Cl}\\)","en":"\\(_{17}\\text{Cl}\\)"},{"ar":"النيون \\(_{10}\\text{Ne}\\)","en":"\\(_{10}\\text{Ne}\\)"},{"ar":"المغنيسيوم \\(_{12}\\text{Mg}\\)","en":"\\(_{12}\\text{Mg}\\)"},{"ar":"البوتاسيوم \\(_{19}\\text{K}\\)","en":"\\(_{19}\\text{K}\\)"}],"answer":2},{"id":"11A-08","qAr":"ما الفلز القلوي الأرضي الذي يستخدم في الأجهزة الإلكترونية لصلابته وخفة وزنه؟","qEn":"Which alkaline earth metal is used in electronic devices for durability and lightness?","options":[{"ar":"الحديد","en":"Iron"},{"ar":"الكالسيوم","en":"Calcium"},{"ar":"المغنيسيوم","en":"Magnesium"},{"ar":"الذهب","en":"Gold"}],"answer":2},{"id":"11A-09","qAr":"أي العبارات غير صحيحة فيما يتعلق بخواص الفلزات القلوية الأرضية؟","qEn":"Which statement is incorrect regarding alkaline earth metals?","options":[{"ar":"أكثر نشاط من الفلزات القلوية","en":"More reactive than alkali metals"},{"ar":"ينتهي توزيعها بتحت المستوى \\(ns^2\\)","en":"Electron configuration ends in \\(ns^2\\)"},{"ar":"تكون أيون شحنته \\((2+)\\)","en":"Form ion with \\((2+)\\) charge"},{"ar":"تفقد إلكتروني التكافؤ بسهولة","en":"Lose two valence electrons easily"}],"answer":0},{"id":"11A-10","qAr":"الهالوجينات مواد مطهرة جيدة. أي مما يلي يُعد هالوجيناً؟","qEn":"Halogens are good disinfectants. Which of the following is a halogen?","options":[{"ar":"N","en":"N"},{"ar":"O","en":"O"},{"ar":"Cl","en":"Cl"},{"ar":"Fe","en":"Fe"}],"answer":2},{"id":"11A-11","qAr":"ما هو المفهوم الأساسي للطاقة في التفاعلات الكيميائية؟","qEn":"What is the basic concept of energy in chemical reactions?","options":[{"ar":"القدرة على بذل شغل أو إنتاج حرارة","en":"Capacity to do work or produce heat"},{"ar":"كمية المادة الصلبة","en":"Amount of solid matter"},{"ar":"سرعة جزيئات الغاز","en":"Speed of gas molecules"},{"ar":"حجم الوعاء","en":"Container volume"}],"answer":0},{"id":"11A-12","qAr":"تحتوي كمية من الحليب على \\(121 \\text{ Cal}\\). كم تساوي هذه الطاقة بوحدة الجول؟","qEn":"Milk contains \\(121 \\text{ Cal}\\). How much is this in joules?","options":[{"ar":"\\(2.3 \\times 10^5 \\text{ J}\\)","en":"\\(2.3 \\times 10^5 \\text{ J}\\)"},{"ar":"\\(2.3 \\times 10^3 \\text{ J}\\)","en":"\\(2.3 \\times 10^3 \\text{ J}\\)"},{"ar":"\\(5.1 \\times 10^5 \\text{ J}\\)","en":"\\(5.1 \\times 10^5 \\text{ J}\\)"},{"ar":"\\(5.1 \\times 10^3 \\text{ J}\\)","en":"\\(5.1 \\times 10^3 \\text{ J}\\)"}],"answer":2},{"id":"11A-13","qAr":"يُطلق تفاعل طارد للحرارة \\(146.4 \\text{ kJ}\\). كم مقدار هذه الطا