40819.png\" alt=\"Copper atoms\"></div>","options":[{"ar":"6.02 × 10²³ ذرة","en":"6.02 × 10²³ atoms"},{"ar":"يساوي العدد الذري","en":"Equals atomic number"},{"ar":"كتلة 1 غرام","en":"Mass of 1 g"},{"ar":"عدد الذرات في 1 غرام نقي","en":"Atoms in 1 g pure Cu"}],"answer":0},{"id":"12A-04","qAr":"أي مما يلي يمثل مول واحد من كلوريد الصوديوم؟","qEn":"Which represents one mole of sodium chloride?","mediaHtml":"<div class=\"q-media\"><img src=\"https://i.postimg.cc/Sx0wW9dh/Screenshot-2026-09-05-141228.png\" alt=\"NaCl formula unit\"></div>","options":[{"ar":"6.02 × 10²³ وحدة صيغة","en":"6.02 × 10²³ formula units"},{"ar":"كتلة 1 غرام ماء","en":"Mass of 1g water"},{"ar":"يساوي العدد الذري للماء","en":"Equals atomic number of water"},{"ar":"كتلة مولية غير محددة","en":"Undefined molar mass"}],"answer":0},{"id":"12A-05","qAr":"أي مما يلي يمثل مول واحد من الماء؟","qEn":"Which represents one mole of water?","mediaHtml":"<div class=\"q-media\"><img src=\"https://i.postimg.cc/jjkVnFk8/Screenshot-2026-09-05-141419.png\" alt=\"Water molecules\"></div>","options":[{"ar":"6.02 × 10²³ جزيء","en":"6.02 × 10²³ molecules"},{"ar":"كتلة 1 غرام","en":"Mass of 1g"},{"ar":"يساوي العدد الذري","en":"Equals atomic number"},{"ar":"عدد ذرات النحاس في 1 غرام","en":"Number of atoms in 1g copper"}],"answer":0},{"id":"12A-06","qAr":"ما عدد الذرات الموجودة في \\(2.50 \\text{ mol}\\) من عنصر \\(\\text{Zn}\\)؟","qEn":"Number of atoms in \\(2.50 \\text{ mol}\\) of \\(\\text{Zn}\\)?","options":[{"ar":"1.51 × 10²⁴ atom","en":"1.51 × 10²⁴ atom"},{"ar":"9.33 × 10²⁴ atom","en":"9.33 × 10²⁴ atom"},{"ar":"1.07 × 10²⁴ atom","en":"1.07 × 10²⁴ atom"},{"ar":"3.02 × 10²⁴ atom","en":"3.02 × 10²⁴ atom"}],"answer":0},{"id":"12A-07","qAr":"ما عدد ذرات \\(\\text{Zn}\\) في \\(3\\) مول من \\(\\text{Zn}\\)?","qEn":"Number of Zn atoms in 3 moles?","options":[{"ar":"1.81 × 10²⁴","en":"1.81 × 10²⁴"},{"ar":"1.2 × 10²⁴","en":"1.2 × 10²⁴"},{"ar":"3.0 × 10²⁴","en":"3.0 × 10²⁴"},{"ar":"2.01 × 10²³","en":"2.01 × 10²³"}],"answer":0},{"id":"12A-08","qAr":"كم عدد مولات \\(\\text{Al}\\) في \\(5.75 \\times 10^{24}\\) ذرة؟","qEn":"Moles in \\(5.75 \\times 10^{24}\\) atoms of \\(\\text{Al}\\)?","options":[{"ar":"9.55 mol Al","en":"9.55 mol Al"},{"ar":"1.05 mol Al","en":"1.05 mol Al"},{"ar":"3.4 mol Al","en":"3.4 mol Al"},{"ar":"5.5 mol Al","en":"5.5 mol Al"}],"answer":0},{"id":"12A-09","qAr":"كم عدد مولات \\(\\text{Fe}\\) في \\(2.5 \\times 10^{20}\\) ذرة؟","qEn":"Moles in \\(2.5 \\times 10^{20}\\) atoms of \\(\\text{Fe}\\)?","options":[{"ar":"4.15 × 10⁻⁴ mol Fe","en":"4.15 × 10⁻⁴ mol Fe"},{"ar":"2.4 × 10³ mol Fe","en":"2.4 × 10³ mol Fe"},{"ar":"2.4 mol Fe","en":"2.4 mol Fe"},{"ar":"1.15 mol Fe","en":"1.15 mol Fe"}],"answer":0},{"id":"12A-10","qAr":"ما معامل التحويل الصحيح لإيجاد عدد الجزيئات من عدد المولات؟","qEn":"Correct conversion factor to find number of molecules from moles?","options":[{"ar":"\\(\\dfrac{6.02 \\times 10^{23}\\text{ molecules}}{1\\text{ mol}}\\)","en":"\\(\\dfrac{6.02 \\times 10^{23}\\text{ molecules}}{1\\text{ mol}}\\)"},{"ar":"\\(\\dfrac{1\\text{ mol}}{6.02 \\times 10^{23}}\\)","en":"\\(\\dfrac{1\\text{ mol}}{6.02 \\times 10^{23}}\\)"},{"ar":"الكتلة المولية","en":"Molar mass"},{"ar":"عدد أفوجادرو مقسوم على الكتلة","en":"Avogadro divided by mass"}],"answer":0},{"id":"12A-11","qAr":"ما معامل التحويل الصحيح لإيجاد عدد المولات من عدد الجزيئات؟","qEn":"Correct conversion factor to find moles from molecules?","options":[{"ar":"\\(\\dfrac{1\\text{ mol}}{6.02 \\times 10^{23}\\text{ molecules}}\\)","en":"\\(\\dfrac{1\\text{ mol}}{6.02 \\times 10^{23}\\text{ molecules}}\\)"},{"ar":"\\(\\dfrac{6.02 \\times 10^{23}}{1\\text{ mol}}\\)","en":"\\(\\dfrac{6.02 \\times 10^{23}}{1\\text{ mol}}\\)"},{"ar":"الكتلة بالجرام","en":"Mass in grams"},{"ar":"الكتلة المولية","en":"Molar mass"}],"answer":0},{"id":"12A-12","qAr":"ما عدد الذرات في \\(3.54 \\text{ mol}\\) من الكبريت \\(\\text{S}\\)?","qEn":"Number of atoms in \\(3.54 \\text{ mol}\\) S?","mediaHtml":"<div class=\"q-media\"><img src=\"https://i.postimg.cc/5N1FR7st/12.png\" alt=\"Sulfur atoms\"></div>","options":[{"ar":"2.13 × 10²⁴","en":"2.13 × 10²⁴"},{"ar":"1.70 × 10²³","en":"1.70 × 10²³"},{"ar":"1.70 × 10²⁴","en":"1.70 × 10²⁴"},{"ar":"2.13 × 10²³","en":"2.13 × 10²³"}],"answer":0},{"id":"12A-13","qAr":"كم عدد الجسيمات الموجودة في مول واحد من أي مادة؟","qEn":"How many particles are present in one mole of any substance?","options":[{"ar":"6.02 × 10²³","en":"6.02 × 10²³"},{"ar":"3.0 × 10⁸","en":"3.0 × 10⁸"},{"ar":"1","en":"1"},{"ar":"123","en":"123"}],"answer":0},{"id":"12A-14","qAr":"إذا كانت كل صورة تمثل مولا واحدا، فأي منها يحتوي على أكبر كمية من المادة؟","qEn":"If each image represents one mole, which contains the greatest amount?","mediaHtml":"<div class=\"q-media\"><img src=\"https://i.postimg.cc/PxYP6YZH/14.png\" alt=\"Moles\"></div>","options":[{"ar":"لا شيء؛ جميع الكميات متساوية (1 مول)","en":"none; all amounts are the same (1 mole)"},{"ar":"جزيئات الماء","en":"water molecules"},{"ar":"ذرات النحاس","en":"copper atoms"},{"ar":"وحدات الصيغة","en":"formula units"}],"answer":0},{"id":"12A-15","qAr":"كم عدد جزيئات السكروز في \\(0.5 \\text{ mol}\\) من السكروز؟","qEn":"How many sucrose molecules in \\(0.5 \\text{ mol}\\) of sucrose?","mediaHtml":"<div class=\"q-media\"><img src=\"https://i.postimg.cc/66V8nVBX/15.png\" alt=\"Sucrose\"></div>","options":[{"ar":"3.01 × 10²³","en":"3.01 × 10²³"},{"ar":"6.02 × 10²³","en":"6.02 × 10²³"},{"ar":"1.20 × 10²⁴","en":"1.20 × 10²⁴"},{"ar":"1.20 × 10²³","en":"1.20 × 10²³"}],"answer":0},{"id":"12A-16","qAr":"أي وحدات العد التالية تكون مناسبة لعد رزم الورق المباعة في متجر؟","qEn":"Which counting unit is appropriate for counting reams of paper?","options":[{"ar":"رزمة (Ream)","en":"ream"},{"ar":"درزن","en":"dozen"},{"ar":"مول","en":"mole"},{"ar":"زوج","en":"pair"}],"answer":0},{"id":"12A-17","qAr":"ما هي الكتلة المولية لعنصر الكربون \\(\\text{C}\\) تقريباً؟","qEn":"What is the approximate molar mass of carbon \\(\\text{C}\\)?","options":[{"ar":"12.011 g/mol","en":"12.011 g/mol"},{"ar":"1.008 g/mol","en":"1.008 g/mol"},{"ar":"15.999 g/mol","en":"15.999 g/mol"},{"ar":"35.45 g/mol","en":"35.45 g/mol"}],"answer":0},{"id":"12A-18","qAr":"كيف تحول الكتلة بالجرام لمركب إلى عدد المولات؟","qEn":"How do you convert mass in grams to moles?","options":[{"ar":"بالقسمة على الكتلة المولية","en":"By dividing by molar mass"},{"ar":"بالضرب في عدد أفوجادرو","en":"By multiplying by Avogadro's number"},{"ar":"بالقسمة على عدد أفوجادرو","en":"By dividing by Avogadro's number"},{"ar":"بالضرب في الكثافة","en":"By multiplying by density"}],"answer":0},{"id":"12A-19","qAr":"ما هي كتلة \\(2.0 \\text{ mol}\\) من الماء \\(\\mathrm{H_2O}\\)? (الكتلة المولية للماء \\(\\approx 18.02\\))","qEn":"What is the mass of \\(2.0 \\text{ mol}\\) of water \\(\\mathrm{H_2O}\\)?","options":[{"ar":"36.04 g","en":"36.04 g"},{"ar":"9.01 g","en":"9.01 g"},{"ar":"18.02 g","en":"18.02 g"},{"ar":"72.08 g","en":"72.08 g"}],"answer":0},{"id":"12A-20","qAr":"ما النسبة المئوية الكتلية للهيدروجين في الماء \\(\\mathrm{H_2O}\\)?","qEn":"What is the mass percent of hydrogen in water \\(\\mathrm{H_2O}\\)?","options":[{"ar":"11.2%","en":"11.2%"},{"ar":"88.8%","en":"88.8%"},{"ar":"50.0%","en":"50.0%"},{"ar":"5.6%","en":"5.6%"}],"answer":0},{"id":"12A-21","qAr":"ما هو الصيغة الأولية لمركب يحتوي على \\(40.0\\%\\) كربون، \\(6.7\\%\\) هيدروجين، و\\(53.3\\%\\) أكسجين؟","qEn":"What is the empirical formula of a compound with \\(40.0\\%\\) C, \\(6.7\\%\\) H, and \\(53.3\\%\\) O?","options":[{"ar":"CH₂O","en":"CH₂O"},{"ar":"C₂H₄O₂","en":"C₂H₄O₂"},{"ar":"CHO","en":"CHO"},{"ar":"CH₃OH","en":"CH₃OH"}],"answer":0},{"id":"12A-22","qAr":"ماذا يقصد بالصيغة الجزيئية للمركب؟","qEn":"What does the molecular formula of a compound represent?","options":[{"ar":"العدد الفعلي للذرات لكل عنصر في الجزيء","en":"Actual number of atoms of each element in a molecule"},{"ar":"أبسط نسبة عددية صحيحة للذرات","en":"Simplest whole-number ratio of atoms"},{"ar":"الكتلة الذرية فقط","en":"Atomic mass only"},{"ar":"نوع الابطال الكيميائي","en":"Bond type"}],"answer":0},{"id":"12A-23","qAr":"ما هو الهيدرات؟","qEn":"What is a hydrate?","options":[{"ar":"مركب أيوني مرتبطة جزيئاته بعدد محدد من جزيئات الماء","en":"Ionic compound bound to a specific number of water molecules"},{"ar":"ماء نقي تماماً","en":"Pure water"},{"ar":"محلول حمضي","en":"Acidic solution"},{"ar":"غاز ذائب في الكحول","en":"Gas dissolved in alcohol"}],"answer":0},{"id":"12A-24","qAr":"كيف تحسب الكتلة المولية لأي مركب كيميائي؟","qEn":"How do you calculate the molar mass of a chemical compound?","options":[{"ar":"بجمع كتل الذرات المكونة له من الجدول الدوري","en":"By summing atomic masses of constituent atoms from periodic table"},{"ar":"بضرب عدد الذرات في عدد أفوجادرو","en":"By multiplying atoms by Avogadro"},{"ar":"بقسمة الكتلة على الحجم","en":"By dividing mass by volume"},{"ar":"بحساب الكثافة النوعية","en":"By calculating specific gravity"}],"answer":0},{"id":"12A-25","qAr":"ما هو حجم مول واحد من أي غاز مثالي في الظروف المعيارية (STP)؟","qEn":"What is the volume of one mole of any ideal gas at STP?","options":[{"ar":"22.4 L","en":"22.4 L"},{"ar":"1.0 L","en":"1.0 L"},{"ar":"100 L","en":"100 L"},{"ar":"24.5 L","en":"24.5 L"}],"answer":0}],"12-متقدم":[{"id":"12P-001","qAr":"ماذا يُعبر عن عملية فقد الإلكترونات أثناء التفاعل الكيميائي؟","qEn":"What term describes the loss of electrons during a chemical reaction?","options":[{"ar":"الاختزال","en":"Reduction"},{"ar":"الأكسدة","en":"Oxidation"},{"ar":"التمييض","en":"Hydrolysis"},{"ar":"التأين","en":"Ionization"}],"answer":1},{"id":"12P-002","qAr":"ما هو عدد التأكسد لعنصر الكلور (Cl₂) في حالته الحرة غير المتفاعلة؟","qEn":"What is the oxidation number of elemental chlorine (Cl₂) in its free state?","options":[{"ar":"-1","en":"-1"},{"ar":"+1","en":"+1"},{"ar":"0","en":"0"},{"ar":"+2","en":"+2"}],"answer":2},{"id":"12P-003","qAr":"أي العبارات التالية <span class='red-key'>غير صحيحة</span> فيما يتعلق بالمعادلة الموضحة أدناه؟","qEn":"Which of the following statements is <span class='red-key'>not true</span> concerning the equation below?","mediaHtml":"<div class=\"q-media\">\\(2\\mathrm{Mg}_{(s)} + \\mathrm{O}_{2(g)} \\rightarrow 2\\mathrm{MgO}_{(s)}\\)</div>","options":[{"ar":"لا يتم انتقال الإلكترونات بين الذرات","en":"No electrons are transferred between atoms"},{"ar":"التفاعل هو أكسدة-اختزال","en":"The reaction is an oxidation-reduction"},{"ar":"تنتقل الإلكترونات بين الذرات","en":"Electrons are transferred between atoms"},{"ar":"تتحول ذرة المغنيسيوم إلى أيون موجب","en":"Magnesium atom is changed to positive ion"}],"answer":0},{"id":"12P-004","qAr":"أي مما يلي يصف <span class='red-key'>الأكسدة</span> بشكل صحيح؟","qEn":"Which of the following describes <span class='red-key'>oxidation</span> correctly?","options":[{"ar":"يفقد المتفاعل الإلكترونات ويزداد عدد تأكسده","en":"A reactant loses electrons and its oxidation number increases"},{"ar":"يفقد المتفاعل الإلكترونات ويقل عدد تأكسده","en":"A reactant loses electrons and its oxidation number decreases"},{"ar":"يكتسب المتفاعل الإلكترونات ويزداد عدد تأكسده","en":"A reactant gains electrons and its oxidation number increases"},{"ar":"يكتسب المتفاعل الإلكترونات ويقل عدد تأكسده","en":"A reactant gains electrons and its oxidation number decreases"}],"answer":0},{"id":"12P-005","qAr":"فيما يتعلق بتفاعل الأكسدة والاختزال أدناه، أي مما يأتي <span class='red-key'>صحيح</span>؟","qEn":"Regarding the redox reaction below. Which of the following is <span class='red-key'>correct</span>?","mediaHtml":"<div class=\"q-media\">\\(\\mathrm{Mg}_{(s)} + \\mathrm{Cl}_{2(g)} \\rightarrow \\mathrm{MgCl}_{2(s)}\\)</div>","options":[{"ar":"تمنح ذرة الكلور إلكترون واحد لكل ذرة مغنيسيوم","en":"Chlorine atom transfers one electron to each magnesium atom"},{"ar":"تمنح ذرة المغنيسيوم إلكترون واحد لكل ذرة كلور","en":"Magnesium atom transfers one electron to each chlorine atom"},{"ar":"تأكسدت ذرة الكلور","en":"Chlorine atom is oxidized"},{"ar":"اختزلت ذرة المغنيسيوم","en":"Magnesium atom is reduced"}],"answer":1},{"id":"12P-006","qAr":"أي العبارات التالية <span class='red-key'>صحيحة</span> فيما يتعلق بالتفاعل أدناه؟","qEn":"Which of the following statements is <span class='red-key'>true</span> concerning the reaction below?","mediaHtml":"<div class=\"q-media\">\\(2\\mathrm{Br}^-_{(aq)} + \\mathrm{Cl}_{2(aq)} \\rightarrow 2\\mathrm{Cl}^-_{(aq)} + \\mathrm{Br}_{2(aq)}\\)</div>","options":[{"ar":"حدوث أكسدة لجزيء الكلور","en":"Oxidation of the chlorine molecule"},{"ar":"انتقال الإلكترونات من أيونات البروميد إلى الكلور","en":"Electrons transfer from bromide ions to chlorine"},{"ar":"انتقال الإلكترونات من الكلور إلى أيونات البروميد","en":"Electrons transfer from chlorine to bromide ions"},{"ar":"حدوث اختزال لأيونات البروميد","en":"Reduction of the bromide ions"}],"answer":1},{"id":"12P-007","qAr":"أي مما يأتي <span class='red-key'>صحيح</span>؟","qEn":"Which of the following is <span class='red-key'>correct</span>?","mediaHtml":"<div class=\"q-media\">\\(2\\mathrm{F}^-_{(aq)} + \\mathrm{I}_{2(aq)} \\longrightarrow \\mathrm{F}_{2(aq)} + 2\\mathrm{I}^-_{(aq)}\\)</div>","options":[{"ar":"تستقبل أيونات الفلوريد الإلكترونات ويحدث لها اختزال","en":"The fluoride ions receive electrons and it is reduced"},{"ar":"تستقبل أيونات الفلوريد وتحدث لها أكسدة","en":"The fluoride ions receive electrons and it is oxidized"},{"ar":"يستقبل اليود وتحدث له أكسدة","en":"The iodine receives electrons and it is oxidized"},{"ar":"يستقبل اليود الإلكترونات ويحدث له اختزال","en":"The iodine receives electrons and it is reduced"}],"answer":3},{"id":"12P-008","qAr":"أي مما يأتي <span class='red-key'>صحيح</span> فيما يتعلق بالتفاعل أدناه؟","qEn":"Which of the following is <span class='red-key'>correct</span> for the reaction below?","mediaHtml":"<div class=\"q-media\">\\(2\\mathrm{Mg}_{(s)} + \\mathrm{O}_{2(g)} \\longrightarrow 2\\mathrm{MgO}_{(s)}\\)</div>","options":[{"ar":"اكتسب الأكسجين إلكترونات وتأكسد","en":"Oxygen gained electrons and was oxidized"},{"ar":"فقدت ذرة المغنيسيوم إلكترونات وتأكسدت","en":"Magnesium atom lost electrons and was oxidized"},{"ar":"فقد الأكسجين إلكترونات وتأكسد","en":"Oxygen lost electrons and was oxidized"},{"ar":"اكتسبت ذرة المغنيسيوم إلكترونات واختزلت","en":"Magnesium atom gained electrons and is reduced"}],"answer":1},{"id":"12P-009","qAr":"أي مما يلي <span class='red-key'>تأكسد</span> في التفاعل التالي؟","qEn":"Which of the following was <span class='red-key'>oxidized</span> in the following reaction?","mediaHtml":"<div class=\"q-media\">\\(2\\mathrm{Na} + 2\\mathrm{H}^+ \\longrightarrow 2\\mathrm{Na}^+ + \\mathrm{H}_2\\)</div>","options":[{"ar":"أيون الصوديوم","en":"Na⁺"},{"ar":"عنصر الصوديوم","en":"Na"},{"ar":"أيون الهيدروجين","en":"H⁺"},{"ar":"غاز الهيدروجين","en":"H₂"}],"answer":1},{"id":"12P-010","qAr":"أي مما يلي هو <span class='red-key'>العامل المختزل</span> في التفاعل التالي؟","qEn":"Which of the following is <span class='red-key'>the reducing agent</span> in the following reaction?","mediaHtml":"<div class=\"q-media\">\\(\\mathrm{Ca}_{(s)} + \\mathrm{Zn}^{2+}_{(aq)} \\longrightarrow \\mathrm{Ca}^{2+}_{(aq)} + \\mathrm{Zn}_{(s)}\\)</div>","options":[{"ar":"الكالسيوم الصلب","en":"Ca(s)"},{"ar":"أيون الزنك","en":"Zn²⁺(aq)"},{"ar":"أيون الكالسيوم","en":"Ca²⁺(aq)"},{"ar":"عنصر الزنك","en":"Zn(s)"}],"answer":0},{"id":"12P-011","qAr":"ما هو <span class='red-key'>العامل المؤكسد</span> في التفاعل التالي؟","qEn":"What is <span class='red-key'>the oxidizing agent</span> in the following reaction?","mediaHtml":"<div class=\"q-media\">\\(\\mathrm{Fe} + 2\\mathrm{Ag}^+ \\longrightarrow \\mathrm{Fe}^{2+} + 2\\mathrm{Ag}\\)</div>","options":[{"ar":"الحديد","en":"Fe"},{"ar":"أيون الفضة","en":"Ag⁺"},{"ar":"أيون الحديد الثنائي","en":"Fe²⁺"},{"ar":"الفضة","en":"Ag"}],"answer":1},{"id":"12P-012","qAr":"أي مما يلي هو <span class='red-key'>العامل المختزل</span> في التفاعل التالي؟","qEn":"Which of the following is <span class='red-key'>the reducing agent</span> in the following reaction?","mediaHtml":"<div class=\"q-media\">\\(2\\mathrm{Ce}_{(s)} + 3\\mathrm{Cu}^{2+}_{(aq)} \\longrightarrow 3\\mathrm{Cu}_{(s)} + 2\\mathrm{Ce}^{3+}_{(aq)}\\)</div>","options":[{"ar":"النحاس","en":"Cu"},{"ar":"أيون النحاس","en":"Cu²⁺"},{"ar":"أيون السيريوم","en":"Ce³⁺"},{"ar":"السيريوم","en":"Ce"}],"answer":3},{"id":"12P-013","qAr":"في التفاعل التالي: <span class='red-key'>أي مما يلي يتم اختزاله</span>؟","qEn":"In the following reaction: <span class='red-key'>which of the following is reduced</span>?","mediaHtml":"<div class=\"q-media\">\\(2\\mathrm{Al} + 3\\mathrm{Cu}^{2+} \\longrightarrow 2\\mathrm{Al}^{3+} + 3\\mathrm{Cu}\\)</div>","options":[{"ar":"أيون الألومنيوم","en":"Al³⁺"},{"ar":"الألومنيوم","en":"Al"},{"ar":"أيون النحاس","en":"Cu²⁺"},{"ar":"النحاس","en":"Cu"}],"answer":2},{"id":"12P-014","qAr":"أي مما يلي يمثل تفاعلاً <span class='red-key'>يحتاج إلى عامل مؤكسد</span>؟","qEn":"Which of the following represents a reaction that <span class='red-key'>requires an oxidizing agent</span>?","options":[{"ar":"Cl₂ + 2e⁻ → 2Cl⁻","en":"Cl₂ + 2e⁻ → 2Cl⁻"},{"ar":"S₂O₄²⁻ + 2H₂O → 3SO₃²⁻ + 4H⁺ + 2e⁻","en":"S₂O₄²⁻ + 2H₂O → 3SO₃²⁻ + 4H⁺ + 2e⁻"},{"ar":"I₂O₅ + 10H⁺ + 10e⁻ → I₂ + 5H₂O","en":"I₂O₅ + 10H⁺ + 10e⁻ → I₂ + 5H₂O"},{"ar":"Cr₂O₇²⁻ + 14H⁺ + 6e⁻ → 2Cr³⁺ + 7H₂O","en":"Cr₂O₇²⁻ + 14H⁺ + 6e⁻ → 2Cr³⁺ + 7H₂O"}],"answer":1},{"id":"12P-015","qAr":"أي التفاعلات النصفية التالية يمثل <span class='red-key'>تفاعل اختزال</span>؟","qEn":"Which of the following half-reactions represents <span class='red-key'>a reduction reaction</span>?","options":[{"ar":"C₂O₄²⁻ → 2CO₂ + 2e⁻","en":"C₂O₄²⁻ → 2CO₂ + 2e⁻"},{"ar":"Cu → Cu²⁺ + 2e⁻","en":"Cu → Cu²⁺ + 2e⁻"},{"ar":"2I⁻ → I₂ + 2e⁻","en":"2I⁻ → I₂ + 2e⁻"},{"ar":"Cr³⁺ + 3e⁻ → Cr","en":"Cr³⁺ + 3e⁻ → Cr"}],"answer":3},{"id":"12P-016","qAr":"يستخدم غاز الكلور لاستخلاص البروم من ماء البحر. والمادة التي تعمل <span class='red-key'>كعامل مؤكسد</span>:","qEn":"Chlorine gas is used to extract bromine from seawater. The substance that acts as <span class='red-key'>an oxidizing agent</span>:","mediaHtml":"<div class=\"q-media\">\\(2\\mathrm{Na}^+ + 2\\mathrm{Br}^- + \\mathrm{Cl}_2 \\longrightarrow 2\\mathrm{Na}^+ + 2\\mathrm{Cl}^- + \\mathrm{Br}_2\\)</div>","options":[{"ar":"غاز الكلور","en":"Cl₂"},{"ar":"أيون الكلوريد","en":"Cl⁻"},{"ar":"أيون البروميد","en":"Br⁻"},{"ar":"أيون الصوديوم","en":"Na⁺"}],"answer":0},{"id":"12P-017","qAr":"أي مما يلي <span class='red-key'>غير صحيح</span> حول انتقال الإلكترونات في الشكل أدناه؟","qEn":"Which of the following is <span class='red-key'>NOT true</span> about electron transfer in the figure below?","mediaHtml":"<div class=\"q-media\"><img src=\"https://i.postimg.cc/nrsMzrp2/Screenshot-2026-09-06-090831.png\" alt=\"Transfer of electrons\"></div>","options":[{"ar":"X يفقد إلكترون","en":"X loses electron"},{"ar":"X عامل مختزل ويتأكسد","en":"X is the reducing agent and becomes oxidized"},{"ar":"عدد تأكسد X يزداد","en":"The oxidation number of X increases"},{"ar":"X عامل مؤكسد ويختزل","en":"X is the oxidizing agent and becomes reduced"}],"answer":3},{"id":"12P-018","qAr":"ما هو <span class='red-key'>العامل المختزل</span> في التفاعل التالي؟","qEn":"What is <span class='red-key'>the reducing agent</span> in the following reaction?","mediaHtml":"<div class=\"q-media\">\\(\\mathrm{H}_2\\mathrm{S}_{(g)} + \\mathrm{Cl}_{2(g)} \\longrightarrow \\mathrm{S}_{(s)} + 2\\mathrm{HCl}_{(g)}\\)</div>","options":[{"ar":"الكلور","en":"Cl₂"},{"ar":"الكبريت","en":"S"},{"ar":"كبريتيد الهيدروجين","en":"H₂S"},{"ar":"حمض الهيدروكلوريك","en":"HCl"}],"answer":2},{"id":"12P-019","qAr":"ما هو <span class='red-key'>العامل المؤكسد</span> في التفاعل التالي؟","qEn":"What is <span class='red-key'>the oxidizing agent</span> in the following reaction?","mediaHtml":"<div class=\"q-media\">\\(\\mathrm{Na}_2\\mathrm{SO}_{4\\,(s)} + 4\\mathrm{C}_{(s)} \\longrightarrow \\mathrm{Na}_2\\mathrm{S}_{(s)} + 4\\mathrm{CO}_{(g)}\\)</div>","options":[{"ar":"الكربون","en":"C"},{"ar":"أول أكسيد الكربون","en":"CO"},{"ar":"كبريتات الصوديوم","en":"Na₂SO₄"},{"ar":"كبريتيد الصوديوم","en":"Na₂S"}],"answer":2},{"id":"12P-020","qAr":"ما هو الترتيب <span class='red-key'>التنازلي</span> الصحيح للصيغ التالية حسب عدد تأكسد <span class='red-key'>الأكسجين</span>؟","qEn":"What is the correct <span class='red-key'>descending</span> order of the following formulas according to <span class='red-key'>oxygen</span>?","mediaHtml":"<div class=\"q-media\">\\(\\mathrm{H}_2\\mathrm{O}_2 \\quad - \\quad \\mathrm{H}_2\\mathrm{O} \\quad - \\quad \\mathrm{O}_2 \\quad - \\quad \\mathrm{OF}_2\\)</div>","options":[{"ar":"H₂O → OF₂ → H₂O₂ → O₂","en":"H₂O → OF₂ → H₂O₂ → O₂"},{"ar":"O₂ → H₂O₂ → OF₂ → H₂O","en":"O₂ → H₂O₂ → OF₂ → H₂O"},{"ar":"OF₂ → O₂ → H₂O₂ → H₂O","en":"OF₂ → O₂ → H₂O₂ → H₂O"},{"ar":"H₂O → H₂O₂ → O₂ → OF₂","en":"H₂O → H₂O₂ → O₂ → OF₂"}],"answer":2},{"id":"12P-021","qAr":"أيّ ممّا يلي يمتلك <span style=\"color:#c62828; font-weight:900;\">أعلى عدد تأكسد</span> للعنصر المكتوب باللون الأحمر في صيغ الأيونات التالية؟","qEn":"Which of the following has the <span style=\"color:#c62828; font-weight:900;\">highest oxidation number</span> for the element written in red in the following ions?","mediaHtml":"<div class=\"q-media\"><img src=\"https://i.postimg.cc/Fz30YmZb/Screenshot-2026-09-15-113454.png\" alt=\"Oxidation Number\"></div>","options":[{"ar":"أيون الكلورات","en":"\\(\\mathrm{ClO_3^-}\\)"},{"ar":"أيون البيرمنجنات","en":"\\(\\mathrm{MnO_4^-}\\)"},{"ar":"أيون الهيبوكلوريت","en":"\\(\\mathrm{ClO^-}\\)"},{"ar":"أيون المنجنات","en":"\\(\\mathrm{MnO_4^{2-}}\\)"}],"answer":1},{"id":"12P-022","qAr":"في معادلة التفاعل أدناه، إذا علمت أن المتفاعل \\(\\mathrm{Cl_2}\\) عامل مؤكسد، فأي ممّا يأتي يصفه صحيحاً؟","qEn":"If \\(\\mathrm{Cl_2}\\) is an oxidizing agent, which of the following describes it correctly?","mediaHtml":"<div class=\"q-media\">\\(\\mathrm{2K_{(s)} + Cl_{2(g)} \\longrightarrow 2KCl_{(s)}}\\)</div>","options":[{"ar":"يكتسب إلكترونات - يزيد - أكسدة","en":"Gains electrons - increases - oxidized"},{"ar":"يفقد إلكترونات - يزيد - أكسدة","en":"Loses electrons - increases - oxidized"},{"ar":"يكتسب إلكترونات - يقل - اختزال","en":"Gains electrons - decreases - reduced"},{"ar":"يفقد إلكترونات - يقل - اختزال","en":"Loses electrons - decreases - reduced"}],"answer":2},{"id":"12P-023","qAr":"فيما يتعلق بتفاعل الأكسدة والاختزال أدناه. أيّ ممّا يأتي صحيح؟","qEn":"Regarding the redox reaction below. Which of the following is correct?","mediaHtml":"<div class=\"q-media\">\\(\\mathrm{2Na + I_2 \\longrightarrow 2NaI}\\)</div>","options":[{"ar":"العامل المؤكسد Na ويتغير من 0 إلى +1","en":"The oxidizing agent is Na and its oxidation number changes from 0 to +1"},{"ar":"العامل المختزل Na ويتغير من 0 إلى +1","en":"The reducing agent is Na and its oxidation number changes from 0 to +1"},{"ar":"العامل المؤكسد I2 ويتغير من 0 إلى +1","en":"The oxidizing agent is I2 and its oxidation number changes from 0 to +1"},{"ar":"العامل المختزل I2 ويتغير من 0 إلى -1","en":"The reducing agent is I2 and its oxidation number changes from 0 to -1"}],"answer":1},{"id":"12P-024","qAr":"في أي الصيغ التالية، يكون عدد تأكسد الهيدروجين <span style=\"color:#c62828; font-weight:900;\">-1</span>؟","qEn":"In which of the following formulas, is the oxidation number of hydrogen <span style=\"color:#c62828; font-weight:900;\">-1</span>?","mediaHtml":"<div class=\"q-media\">\\(\\mathrm{H_2O \\quad \\text{—} \\quad H_2O_2 \\quad \\text{—} \\quad H_2 \\quad \\text{—} \\quad KH}\\)</div>","options":[{"ar":"ماء","en":"\\(\\mathrm{H_2O}\\)"},{"ar":"فوق أكسيد الهيدروجين","en":"\\(\\mathrm{H_2O_2}\\)"},{"ar":"غاز الهيدروجين","en":"\\(\\mathrm{H_2}\\)"},{"ar":"هيدريد الليثيوم","en":"\\(\\mathrm{KH}\\)"}],"answer":3},{"id":"12P-025","qAr":"في التفاعل الآتي، أيّ ممّا يلي يسلك كـ <span style=\"color:#c62828; font-weight:900;\">عامل مؤكسد وعامل مختزل في آنٍ واحد</span>?","qEn":"In the following reaction, which of the following acts as <span style=\"color:#c62828; font-weight:900;\">both an oxidizing agent and a reducing agent at the same time</span>?","mediaHtml":"<div class=\"q-media\">\\(\\mathrm{Cl_{2(g)} + 2OH^-_{(aq)} \\longrightarrow Cl^-_{(aq)} + ClO^-_{(aq)} + H_2O_{(l)}}\\)</div>","options":[{"ar":"الكلور (Cl₂)","en":"Chlorine (Cl₂)"},{"ar":"أيون الهيدروكسيد (OH⁻)","en":"Hydroxide ion (OH⁻)"},{"ar":"أيون الكلوريد (Cl⁻)","en":"Chloride ion (Cl⁻)"},{"ar":"الماء (H₂O)","en":"Water (H₂O)"}],"answer":0}]}$legacy_banks$::jsonb);
